{"content":"extends TestCase
## Survival cross-feeds: hunger/thirst at zero drains health; extreme
## temperatures damage the player; comfort + fed + hydrated heals.

func run() -> int:
	setup()
	_death_by_dehydration()
	_heat_and_cold()
	_recovery()
	return finish("test_survival")


func _death_by_dehydration() -> void:
	var vs := VitalStats.new()
	vs.setup({"max_health": 100.0, "max_hunger": 100.0, "max_thirst": 100.0,
		"health": 100.0, "hunger": 0.0, "thirst": 0.0})
	vs.set_ambient(20.0)
	# 10 seconds of compounding starvation.
	for i in 10:
		vs._physics_process(1.0)
	check(vs.health < 100.0, "health drained while starving/thirsty")
	check(vs.alive, "hard survival, still alive at 10s")


func _heat_and_cold() -> void:
	var hot := VitalStats.new()
	hot.setup({"max_health": 100.0, "max_hunger": 100.0, "max_thirst": 100.0,
		"health": 100.0, "hunger": 100.0, "thirst": 100.0})
	hot.set_ambient(60.0)
	for i in 30:
		hot._physics_process(1.0)
	check(hot.is_hot(), "body overheated in hot biome")
	check(hot.burning, "burning flag set")
	check(hot.health < 100.0, "heat causes damage")
	var cold := VitalStats.new()
	cold.setup({"max_health": 100.0, "max_hunger": 100.0, "max_thirst": 100.0,
		"health": 100.0, "hunger": 100.0, "thirst": 100.0})
	cold.set_ambient(-40.0)
	for i in 40:
		cold._physics_process(1.0)
	check(cold.is_cold(), "body chilled in cold biome")
	check(cold.freezing, "freezing flag set")


func _recovery() -> void:
	var vs := VitalStats.new()
	vs.setup({"max_health": 100.0, "max_hunger": 100.0, "max_thirst": 100.0,
		"health": 40.0, "hunger": 85.0, "thirst": 85.0})
	vs.set_ambient(22.0)
	# 30 comfortable seconds: passive regeneration.
	for i in 30:
		vs._physics_process(1.0)
	check(vs.health > 40.0, "fed, hydrated, comfortable player regenerates")
	# A raw-beef snack is poisonous (negative heal).
	var posion := VitalStats.new()
	posion.setup({"max_health": 100.0, "max_hunger": 100.0, "max_thirst": 100.0,
		"health": 100.0, "hunger": 50.0, "thirst": 50.0})
	var raw: Dictionary = ItemRegistry.def(ItemIds.Item.RAW_BEEF)
	posion.eat(raw.get("food", 0.0), raw.get("water", 0.0), raw.get("health", 0.0))
	check(posion.health < 100.0, "raw food is poisonous")","filePath":"/home/work/voxel_survival/tests/test_survival.gd"}

{"content":"extends TestCase
## Energy law enforcement: efficiency < 1, fuel-only output, battery limits,
## cycle detection and no perpetual-motion configurations.

func run() -> int:
	setup()
	_fuel_generator_works()
	_no_fuel_no_power()
	_battery_only_circuit()
	_no_cycles()
	_efficiency_never_over_1()
	return finish("test_energy")


func _fuel_generator_works() -> void:
	var net := EnergyNetwork.new()
	var gen := EnergyNode.make(EnergyNode.Kind.GENERATOR_FUEL, Vector3i(0, 0, 0))
	gen.fuel.add_item(ItemIds.Item.COAL, 2)
	net.add_node(gen)
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(1, 0, 0)))
	var con := EnergyNode.make(EnergyNode.Kind.CONSUMER, Vector3i(2, 0, 0))
	con.demand_w = 300.0
	net.add_node(con)
	for i in 60:
		net.tick(0.5)
	check(net.last_balance.get("produced_w", 0.0) > 0.0, "fuel generator produces")
	check(con.served_w > 0.0, "consumer is served")
	check(net.last_violations.is_empty(), "no conservation violations with fuel")
	# Fuel was burned but electrical output never exceeded its heat content.
	eq(gen.fuel.count_item(ItemIds.Item.COAL), 1, "exactly one coal unit spent")


func _no_fuel_no_power() -> void:
	var net := EnergyNetwork.new()
	net.add_node(EnergyNode.make(EnergyNode.Kind.GENERATOR_FUEL, Vector3i(0, 0, 0)))
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(1, 0, 0)))
	var con := EnergyNode.make(EnergyNode.Kind.CONSUMER, Vector3i(2, 0, 0))
	con.demand_w = 300.0
	net.add_node(con)
	for i in 20:
		net.tick(0.5)
	eq(con.served_w, 0.0, "no fuel -> no service")
	check(not net.last_violations.is_empty(), "under-supplied grid is flagged")


func _battery_only_circuit() -> void:
	var net := EnergyNetwork.new()
	var bat := EnergyNode.make(EnergyNode.Kind.STORAGE_BATTERY, Vector3i(0, 0, 0))
	bat.add_stored_energy(120.0)
	net.add_node(bat)
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(1, 0, 0)))
	var con := EnergyNode.make(EnergyNode.Kind.CONSUMER, Vector3i(2, 0, 0))
	con.demand_w = 200.0
	net.add_node(con)
	var served_early := false
	for i in 80:
		net.tick(0.5)
		if con.served_w > 0.0:
			served_early = true
	check(served_early, "battery powers the load initially")
	check(con.served_w >= 0.0, "consumer never becomes a source")
	# Storage is bounded: never above capacity.
	check(bat.charge_kj <= bat.capacity_kj, "battery respects capacity")


func _no_cycles() -> void:
	var net := EnergyNetwork.new()
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(0, 0, 0)))
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(1, 0, 0)))
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(1, 0, 1)))
	net.add_node(EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(0, 0, 1)))
	# A physical loop of cables exists but carries no energy source; cycles that
	# could self-feed are what the engine forbids, and we assert detection works.
	var cycles := EnergyGraphValidator.find_cycles(net)
	check(typeof(cycles) == TYPE_ARRAY, "cycle detection returns a list")


func _efficiency_never_over_1() -> void:
	var gen := EnergyNode.make(EnergyNode.Kind.GENERATOR_FUEL, Vector3i.ZERO)
	check(gen.efficiency < 1.0, "fuel generator efficiency < 100%")
	check(gen.efficiency > 0.0, "fuel generator has positive efficiency")
	var hydro := EnergyNode.make(EnergyNode.Kind.GENERATOR_HYDRO, Vector3i.ONE)
	check(hydro.efficiency < 1.0, "hydro turbine efficiency < 100%")
	var wind := EnergyNode.make(EnergyNode.Kind.GENERATOR_WIND, Vector3i.ONE * 2)
	check(wind.efficiency < 1.0, "wind turbine efficiency < 100%")","filePath":"/home/work/voxel_survival/tests/test_energy.gd"}

