	# 2) Producers release available outputs.
	var comps := connected_components()
	for comp in comps:
		var prod_w := 0.0
		var stored_kj := 0.0
		var demand_comp := 0.0
		var switches_on := _comps_wired_on(comp)
		for pos in comp:
			var n: EnergyNode = nodes[pos]
			if not switches_on and pos != comp[0]:
				n.served_w = 0.0
				continue
			match n.kind:
				EnergyNode.Kind.GENERATOR_FUEL:
					prod_w += _fuel_output(n, dt)
				EnergyNode.Kind.GENERATOR_WIND:
					prod_w += _wind_output(n, dt)
				EnergyNode.Kind.GENERATOR_HYDRO:
					prod_w += _hydro_output(n, dt)
				EnergyNode.Kind.STORAGE_BATTERY:
					stored_kj += n.charge_kj
				EnergyNode.Kind.CONSUMER:
					if n.enabled:
						demand_comp += n.demand_w
		# 3) Balance: battery discharge fills gaps, charge from surplus.
		var power_balance := prod_w - demand_comp
		for pos in comp:
			var n: EnergyNode = nodes[pos]
			if n.kind != EnergyNode.Kind.STORAGE_BATTERY:
				continue
			if power_balance > 0.0:
				var charge := minf(power_balance, n.charge_rate_w)
				n.add_stored_energy(charge * dt / 1000.0)
				power_balance -= charge
			elif power_balance < 0.0:
				var deliver := minf(-power_balance, n.delivery_rate_w)
